sys_script_client.script:
function onSubmit() {
    if (g_scratchpad.is_validated == true) {
        return true;
    }

    var baseId = g_form.getUniqueValue();
    var baseName = g_form.getValue('name'); 
    var baseCity = g_form.getValue('city');
    var baseState = g_form.getValue('state');
    var maxCapacity = parseInt(g_form.getValue('max_capacity'), 10);

    if (!baseName || !baseCity || !baseState) {
        return true;
    }

    g_form.clearMessages();

    // Validação max_capacity
    if (isNaN(maxCapacity) || maxCapacity < 1) {
        g_form.setValue('max_capacity', '');
        g_form.showFieldMsg('max_capacity', 'Max Capacity must be greater than or equal to 1.', 'error');
        return false;
    }

    // Validação name - sem espaços no início e fim
    if (/^\s|\s$/.test(baseName)) {
        g_form.setValue('name', '');
        g_form.showFieldMsg('name', 'Name must not have leading or trailing spaces.', 'error');
        return false;
    }

    // Validação city - sem espaços no início e fim
    if (/^\s|\s$/.test(baseCity)) {
        g_form.setValue('city', '');
        g_form.showFieldMsg('city', 'City must not have leading or trailing spaces.', 'error');
        return false;
    }
    // Validação city - sem números e caracteres especiais
    if (/[^a-zA-ZÀ-ÿ\s]/.test(baseCity)) {
        g_form.setValue('city', '');
        g_form.showFieldMsg('city', 'City must contain only letters.', 'error');
        return false;
    }

    // Validação state - sem espaços no início e fim
    if (/^\s|\s$/.test(baseState)) {
        g_form.setValue('state', '');
        g_form.showFieldMsg('state', 'State must not have leading or trailing spaces.', 'error');
        return false;
    }
    // Validação state - sem números e caracteres especiais
    if (/[^a-zA-ZÀ-ÿ\s]/.test(baseState)) {
        g_form.setValue('state', '');
        g_form.showFieldMsg('state', 'State must contain only letters.', 'error');
        return false;
    }

    var ga = new GlideAjax('BaseValidation'); 
    ga.addParam('sysparm_name', 'validateBaseDuplicity');
    ga.addParam('sysparm_base_id', baseId);
    ga.addParam('sysparm_base_name', baseName);
    ga.addParam('sysparm_base_city', baseCity);
    ga.addParam('sysparm_base_state', baseState);

    ga.getXML(processResponse);

    return false;

    function processResponse(response) {
        var answer = response.responseXML.documentElement.getAttribute("answer");

        g_form.clearMessages();

        if (answer == 'duplicate_name') {
            g_form.addErrorMessage('Unable to save: A base with the name "' + baseName + '" already exists. Please choose a unique name.');
            g_form.setValue('name', ''); 
            g_scratchpad.is_validated = false;
        } 
        else if (answer == 'duplicate_location') {
            g_form.addErrorMessage('Unable to save: A base is already registered for this City and State combination (' + baseCity + ' - ' + baseState + '). Duplicate locations are not allowed.');
            g_form.setValue('city', '');
            g_form.setValue('state', '');
            g_scratchpad.is_validated = false;
        } 
        else if (answer == 'ok') {
            g_scratchpad.is_validated = true;

            if (g_form.isNewRecord()) {
                g_form.submit();
            } else {
                g_form.save();
            }
        }
    }
}
